{"sql": "WITH customer_date_range AS (
    SELECT customer_id, MIN(txn_date::DATE) as min_date, MAX(txn_date::DATE) as max_date
    FROM customer_transactions
    GROUP BY customer_id
),
all_dates AS (
    SELECT customer_id, generate_series(min_date, max_date, INTERVAL '1 day')::DATE as txn_date
    FROM customer_date_range
)
SELECT * FROM all_dates LIMIT 10"}

